package main

import (
	"context"
	"fmt"
	"os"
	"time"

	"procrace/process"
)

func main() {
	mode := os.Args[1]
	switch mode {
	case "race":
		size := 200 * 1024
		if len(os.Args) > 2 {
			fmt.Sscanf(os.Args[2], "%d", &size)
		}
		runs := 300
		if len(os.Args) > 3 {
			fmt.Sscanf(os.Args[3], "%d", &runs)
		}
		script := fmt.Sprintf(`dd if=/dev/zero bs=1024 count=%d 2>/dev/null | tr "\\0" a`, size/1024)
		lost, trunc := 0, 0
		minLen := size
		for i := 0; i < runs; i++ {
			result, err := (process.DirectRunner{}).Run(context.Background(), process.Request{
				Executable: "/bin/sh", Args: []string{"-c", script},
				Dir: "/tmp", Env: []string{"PATH=/usr/bin:/bin"}, Timeout: 30 * time.Second,
			})
			if err != nil {
				fmt.Println("run error:", err)
				continue
			}
			if len(result.Stdout) != size {
				lost++
				if len(result.Stdout) < minLen {
					minLen = len(result.Stdout)
				}
			}
			if result.StdoutTruncated {
				trunc++
			}
		}
		fmt.Printf("size=%d runs=%d lost-tail=%d truncated-flag=%d min-len=%d\n", size, runs, lost, trunc, minLen)
	case "setsid":
		start := time.Now()
		result, err := (process.DirectRunner{}).Run(context.Background(), process.Request{
			Executable: "/bin/sh",
			Args:       []string{"-c", `setsid sh -c 'sleep 4' >/proc/self/fd/1 2>&1 & echo leader-done`},
			Dir:        "/tmp", Env: []string{"PATH=/usr/bin:/bin"}, Timeout: 500 * time.Millisecond, CleanupGrace: 100 * time.Millisecond,
		})
		elapsed := time.Since(start)
		fmt.Printf("elapsed=%v timed-out=%v cancelled=%v cleanup-complete=%v stdout=%q err=%v\n", elapsed.Round(time.Millisecond), result.TimedOut, result.Cancelled, result.CleanupComplete, result.Stdout, err)
	}
}
EOF
go build -o /tmp/opencode/procrace/procrace . && echo BUILD-OK

